import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { checkFixture, makeReplay, replay } from '../src/harness.js';
import { parseText } from './consumers.js';

// Hand-written synthetic input and oracle, not output generated by the parser.
export function createFixture() {
  return {
    name: 'custom-greeting',
    bytes: new TextEncoder().encode('event: greeting\nid: demo-1\ndata: hello 🌊\n\n'),
    expected: [{ type: 'greeting', data: 'hello 🌊', lastEventId: 'demo-1' }],
  };
}

// Replace this body with your parser adapter. Create state inside each call;
// normalize every event to exactly these three string fields. Async is allowed.
// parseText is an illustrative, buffered parser, not a production SSE client.
export function consumer(chunks) {
  const decoder = new TextDecoder();
  let text = '';
  for (const chunk of chunks) text += decoder.decode(chunk, { stream: true });
  text += decoder.decode(); // Flush once when this input finishes.
  return parseText(text).map(({ type, data, lastEventId }) => ({ type, data, lastEventId }));
}

// Negative control only: a new decoder per chunk corrupts split UTF-8.
export function brokenConsumer(chunks) {
  return parseText(chunks.map(chunk => new TextDecoder().decode(chunk)).join(''));
}

export async function runRecipe() {
  const fixture = createFixture();
  const options = { randomCases: 0, singleSplitLimit: 256 };
  const good = await checkFixture(consumer, fixture, options);
  assert.equal(good.passed, true);

  const report = await checkFixture(brokenConsumer, fixture, options);
  const failedCase = report.cases.find(c => !c.matchesExpected || !c.chunkInvariant);
  // Your consumer may have no failures: never call makeReplay with undefined.
  assert.ok(failedCase, 'the negative control must fail before creating a replay');
  const json = JSON.stringify(makeReplay(fixture, report, failedCase), null, 2);
  // This string can be saved with fs.writeFile, but the recipe writes no files.
  const artifact = JSON.parse(json);
  const broken = await replay(brokenConsumer, artifact);
  const fixed = await replay(consumer, artifact);
  assert.equal(broken.matchesExpected, false);
  assert.equal(broken.chunkInvariant, false);
  assert.equal(fixed.matchesExpected, true);
  assert.equal(fixed.chunkInvariant, true);
  return { fixture, good, report, artifact, json, broken, fixed };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { fixture, good, artifact } = await runRecipe();
  console.log('StreamSplit: test your own consumer');
  console.log(`Custom fixture: ${fixture.bytes.length} bytes; ${good.cases.length} partitions`);
  console.log('PASS: streaming adapter matches the hand-written expected event');
  console.log(`Captured failure: cuts ${JSON.stringify(artifact.cuts)}; JSON replay v${artifact.version}`);
  console.log('PASS: serialized replay fails with broken decoder and passes with streaming adapter');
}
